const projectId = $input.item.json.result;
const lead = $('Fetch Lead + Deal Detail').item.json;
const today = new Date();
function plusDays(n) {
  const d = new Date(today);
  d.setDate(d.getDate() + n);
  return d.toISOString().slice(0, 10);
}

// Standard onboarding task template -- v1 fixed list, v2: pull from a per-service_type template table
const tasks = [
  { name: 'Kickoff call scheduled', days: 2 },
  { name: 'Collect access & credentials (website, ad accounts, socials)', days: 3 },
  { name: 'Collect brand assets (logo, guidelines, past creatives)', days: 3 },
  { name: 'Assign delivery team + internal handoff note', days: 1 },
  { name: 'Draft 30-day strategy doc', days: 7 },
  { name: 'First deliverable due', days: 14 }
];

return [{
  json: {
    ...lead,
    odoo_project_id: projectId,
    task_create_args: tasks.map(t => ({
      name: t.name,
      project_id: projectId,
      date_deadline: plusDays(t.days)
    }))
  }
}];

const lead = $('Fetch Lead + Deal Detail').item.json;
let shareUrl = '';
try {
  shareUrl = JSON.parse($('Nextcloud - Create Client Share Link').item.json.data || '{}').ocs?.data?.url || '';
} catch (e) {
  shareUrl = $('Nextcloud - Create Client Share Link').item.json.url || '';
}

return [{
  json: {
    ...lead,
    client_folder_url: shareUrl,
    odoo_project_id: $('Build Onboarding Task List').item.json.odoo_project_id,
    odoo_discuss_channel_id: $('Odoo - Create Client Discuss Channel').item.json.result
  }
}];

